#!/bin/bash
# Publishes every PC truth fixture from the build outputs under $B (the layout scripts_*.sh and the cmake
# builds write). usage: publish_all.sh [ids...]   (default: all)
set -e
R=~/runs/PcImport; B=$R/build; C=~/ventris-corpus/extracted; T=$R/pc_truth.py
want=" $* "
M8="MSVC 14.00.50727.42 (Visual C++ 2005, widberg/msvc8.0@936f93b9e9e92943ed5c9398d24712a32c2e9fe4: cl.exe 14.00.50727.42 + link.exe 8.00.50727.42 under wine 11.0 / Fedora wine-core 11.0-3.fc44), static CRT libcmt.lib 8.0"
MG32="GCC 16.2.1 MinGW-w64 13.0.0 (Fedora 44 mingw32-gcc 16.2.1-1.fc44), i686-w64-mingw32, GNU ld 2.46"
MG64="GCC 16.2.1 MinGW-w64 13.0.0 (Fedora 44 mingw64-gcc 16.2.1-1.fc44), x86_64-w64-mingw32, GNU ld 2.46"
Q2="https://github.com/id-Software/Quake-2"; Q2C=372afde46e7defc9dd2d719a1732b8ace1fa096e
IOQ="https://github.com/ioquake/ioq3"; IOQC=87a99d18206e878a20289f05ac3c16005dcae5c3
pub() { id=$1; shift; if [ "$want" = "  " ] || [[ "$want" == *" $id "* ]]; then rm -rf $C/$id; python3 $T "$@" --out $C/$id --id $id; fi; }
pub pc-ioq3-ded-mingw32 --kind dwarf --exe $B/ioq3-mingw32/RelWithDebInfo/ioq3ded.exe --game "ioquake3 dedicated server (Quake III Arena engine)" --compiler "$MG32" --flags "-fno-lto -msse -mfpmath=387 -O2 -g -DNDEBUG -std=gnu99 -fno-strict-aliasing -fvisibility=hidden (cmake RelWithDebInfo, warnings omitted)" --repo $IOQ --commit $IOQC --license GPL-2.0-or-later --provenance "cmake (benchmarks/pc_fixtures.md); image = llvm-strip --strip-all of truth/build/ioq3ded.exe; truth = DW_TAG_subprogram low/high pc (llvm-dwarfdump) + COFF function symbols and import-stub symbols (size 0)"
pub pc-ioq3-ded-mingw64 --kind dwarf --exe $B/ioq3-mingw64/RelWithDebInfo/ioq3ded.exe --game "ioquake3 dedicated server (Quake III Arena engine), x86-64" --compiler "$MG64" --flags "-fno-lto -O2 -g -DNDEBUG -std=gnu99 -fno-strict-aliasing -fvisibility=hidden (cmake RelWithDebInfo, warnings omitted)" --repo $IOQ --commit $IOQC --license GPL-2.0-or-later --provenance "image = llvm-strip --strip-all of truth/build/ioq3ded.exe; truth = DW_TAG_subprogram low/high pc + COFF function symbols and import-stub symbols (size 0)"
pub pc-doomgeneric-mingw32 --kind dwarf --exe $B/doom-mingw32/doomgeneric.exe --keep $B/doom-mingw32/doomgeneric.map --game "doomgeneric (DOOM engine, Win32 GDI frontend)" --compiler "$MG32" --flags "-O2 -g -DSNDSERV -D_DEFAULT_SOURCE -w (one gcc invocation, no --gc-sections)" --repo https://github.com/ozkl/doomgeneric --commit e257a09527062bfb986b6e5e0780839b6cbd5b71 --license GPL-2.0-or-later --provenance "scripts_doom_mingw.sh i686; Windows.h include-case shim; truth = DWARF subprograms + COFF function symbols + import-stub symbols"
pub pc-quake2-msvc8 --kind pdb --exe $B/q2-msvc8/quake2.exe --pdb $B/q2-msvc8/quake2.pdb --game "Quake 2 client+server (null sound; ref DLLs loaded)" --compiler "$M8" --flags "/O2 /MT /Zi /D WIN32 /D NDEBUG /D _WINDOWS /D _CRT_SECURE_NO_DEPRECATE /D _CRT_NONSTDC_NO_DEPRECATE /W1 (default /GS); link /DEBUG /MAP /INCREMENTAL:NO /SUBSYSTEM:WINDOWS" --repo $Q2 --commit $Q2C --license GPL-2.0-or-later --provenance "scripts_q2_msvc8.sh; client/ qcommon/ server/ game/q_shared.c game/m_flash.c win32/{cd_win,conproc,in_win,net_wins,q_shwin,sys_win,vid_dll,vid_menu}.c null/snddma_null.c + build shims (a dsound.h with two typedefs, S_Activate stub); truth = S_GPROC32/S_LPROC32 (llvm-pdbutil) + PDB public function symbols"
pub pc-quake2-game-msvc8 --kind pdb --exe $B/q2dll-msvc8/game/gamex86.dll --pdb $B/q2dll-msvc8/game/gamex86.pdb --game "Quake 2 game module gamex86.dll" --compiler "$M8" --flags "/O2 /MT /Zi /D WIN32 /D NDEBUG /D _WINDOWS /D _CRT_SECURE_NO_DEPRECATE /D _CRT_NONSTDC_NO_DEPRECATE /W1 (default /GS); link /DLL /DEBUG /MAP /DEF:game.def" --repo $Q2 --commit $Q2C --license GPL-2.0-or-later --provenance "scripts_q2dll_msvc8.sh; game/*.c; truth = PDB"
pub pc-quake2-refgl-msvc8 --kind pdb --exe $B/q2dll-msvc8/refgl/ref_gl.dll --pdb $B/q2dll-msvc8/refgl/ref_gl.pdb --game "Quake 2 OpenGL renderer ref_gl.dll" --compiler "$M8" --flags "/O2 /MT /Zi /D WIN32 /D NDEBUG /D _WINDOWS /D _CRT_SECURE_NO_DEPRECATE /D _CRT_NONSTDC_NO_DEPRECATE /W1 (default /GS); link /DLL /DEBUG /MAP /DEF:ref_gl.def" --repo $Q2 --commit $Q2C --license GPL-2.0-or-later --provenance "scripts_q2dll_msvc8.sh; ref_gl/*.c game/q_shared.c win32/{q_shwin,glw_imp,qgl_win}.c; truth = PDB"
pub pc-glquake-msvc42 --kind coff --exe $B/wq-msvc42/glquake-debug.exe --image $B/wq-msvc42/glquake.exe --image-name glquake.exe --keep $B/wq-msvc42/glquake.map $B/wq-msvc42/glquake-debug.map --game "GLQuake (Quake 1, WinQuake GL Release target, C-only, no DirectInput mouse path)" --compiler "MSVC 10.20 (Visual C++ 4.2, itsmattkc/msvc420@df2c13aad74c094988c6c7e784234c2e778a0e91: cl.exe/link.exe 4.20 under wine 11.0), static CRT libc.lib 4.2" --flags "/O2 /G5 /ML /Z7 /D WIN32 /D NDEBUG /D _WINDOWS /D GLQUAKE; link /OPT:REF /SUBSYSTEM:WINDOWS /INCREMENTAL:NO (image) + /DEBUG /DEBUGTYPE:COFF (truth link)" --repo https://github.com/id-Software/Quake --commit bf4ac424ce754894ac8f1dae6a3981954bc9852d --license GPL-2.0-or-later --provenance "scripts_wq_msvc42.sh; GL Release target sources in a copy with the x86-assembly switch off (quakedef.h/quakeasm.h id386=0, sys_win.c FPU stubs) and a dinput.h shim (the DirectInput mouse path is compiled, the calls type-check only); truth = COFF function symbols of the debug link (same .text layout), size = to the next function symbol minus trailing int3/nop fill (includes a switch table placed after a function)"
pub pc-quake2-game-msvc8-debug --kind pdb --exe $B/q2game-msvc8-debug/gamex86.dll --pdb $B/q2game-msvc8-debug/gamex86.pdb --game "Quake 2 game module gamex86.dll, Debug build with an incremental link table" --compiler "$M8" --flags "/Od /RTC1 /MTd /Zi /D WIN32 /D _DEBUG /D _WINDOWS /D _CRT_SECURE_NO_DEPRECATE /D _CRT_NONSTDC_NO_DEPRECATE /W1; link /DLL /DEBUG /INCREMENTAL /DEF:game.def" --repo $Q2 --commit $Q2C --license GPL-2.0-or-later --provenance "scripts_q2game_msvc8_debug.sh; game/*.c; truth = PDB + the 5-byte jmp entries of the incremental link table (the * Linker * module's contribution)"
